<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(18, 24, 45, 0.92);
        --panel-strong: #12192f;
        --border: rgba(148, 163, 184, 0.2);
        --text: #f8fafc;
        --muted: #94a3b8;
        --accent: #8b5cf6;
        --accent-strong: #7c3aed;
        --danger: #ef4444;
        --danger-strong: #dc2626;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(139, 92, 246, 0.3), transparent 32%),
          linear-gradient(180deg, #0f172a 0%, var(--bg) 100%);
        color: var(--text);
      }

      button {
        font: inherit;
      }

      .app-shell {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .preview-card {
        width: min(100%, 720px);
        background: var(--panel);
        border: 1px solid var(--border);
        border-radius: 28px;
        padding: 24px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .eyebrow {
        margin: 0 0 8px;
        color: var(--accent);
        text-transform: uppercase;
        letter-spacing: 0.14em;
        font-size: 0.78rem;
        font-weight: 700;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.8rem, 4vw, 2.5rem);
      }

      .subcopy {
        margin: 12px 0 24px;
        color: var(--muted);
        line-height: 1.5;
      }

      .image-frame {
        margin: 0;
        overflow: hidden;
        border-radius: 22px;
        border: 1px solid var(--border);
        background: #020617;
      }

      .image-frame img {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 10;
        object-fit: cover;
      }

      .caption-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 16px 18px;
        background: rgba(2, 6, 23, 0.7);
      }

      .caption-title {
        margin: 0;
        font-size: 1rem;
        font-weight: 600;
      }

      .caption-meta {
        margin: 4px 0 0;
        color: var(--muted);
        font-size: 0.92rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 20px;
      }

      .button {
        border: 0;
        border-radius: 999px;
        padding: 12px 18px;
        color: var(--text);
        cursor: pointer;
        transition: transform 160ms ease, background-color 160ms ease, opacity 160ms ease;
      }

      .button:hover {
        transform: translateY(-1px);
      }

      .button:focus-visible {
        outline: 2px solid #c4b5fd;
        outline-offset: 3px;
      }

      .button-secondary {
        background: rgba(148, 163, 184, 0.16);
      }

      .button-secondary:hover {
        background: rgba(148, 163, 184, 0.24);
      }

      .button-danger {
        background: linear-gradient(180deg, var(--danger), var(--danger-strong));
        box-shadow: 0 14px 30px rgba(220, 38, 38, 0.28);
      }

      .button-danger:hover {
        background: linear-gradient(180deg, #f87171, var(--danger));
      }

      .dialog {
        width: min(100% - 32px, 440px);
        border: 1px solid var(--border);
        border-radius: 24px;
        padding: 24px;
        background: linear-gradient(180deg, rgba(15, 23, 42, 0.96), rgba(15, 23, 42, 0.9));
        color: var(--text);
        box-shadow: var(--shadow);
      }

      .dialog::backdrop {
        background: rgba(2, 6, 23, 0.72);
        backdrop-filter: blur(8px);
      }

      .dialog h2 {
        margin: 0 0 10px;
        font-size: 1.4rem;
      }

      .dialog p {
        margin: 0;
        color: var(--muted);
        line-height: 1.55;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 24px;
      }

      .empty-state {
        display: grid;
        place-items: center;
        min-height: 280px;
        border: 1px dashed rgba(148, 163, 184, 0.24);
        border-radius: 22px;
        background: rgba(2, 6, 23, 0.45);
        text-align: center;
        padding: 24px;
      }

      .empty-state p {
        margin: 0;
        color: var(--muted);
      }
    </style>
  </head>
  <body>
    <div id="app"></div>

    <script>
      const root = document.getElementById("app");

      const state = {
        isDeleted: false,
      };

      function App() {
        return `
          <main class="app-shell">
            ${ImagePreviewPage()}
            ${DeleteImageDialog()}
          </main>
        `;
      }

      function ImagePreviewPage() {
        return `
          <section class="preview-card" aria-labelledby="page-title">
            <p class="eyebrow">Library</p>
            <h1 id="page-title">Image preview</h1>
            <p class="subcopy">Review this image before you keep editing or remove it from your library.</p>
            ${
              state.isDeleted
                ? `
                  <div class="empty-state" aria-live="polite">
                    <p>The image has been removed from your library.</p>
                  </div>
                `
                : `
                  <figure class="image-frame">
                    <img
                      src="https://images.unsplash.com/photo-1511300636408-a63a89df3482?auto=format&fit=crop&w=1200&q=80"
                      alt="Neon-lit city street reflected on wet pavement at night"
                    />
                    <figcaption class="caption-row">
                      <div>
                        <p class="caption-title">Night Streetscape</p>
                        <p class="caption-meta">4096 x 2560 px</p>
                      </div>
                    </figcaption>
                  </figure>
                  <div class="actions">
                    <button type="button" class="button button-danger trigger" data-open-dialog>
                      Delete image
                    </button>
                  </div>
                `
            }
          </section>
        `;
      }

      function DeleteImageDialog() {
        return `
          <dialog class="dialog" id="delete-dialog" aria-labelledby="dialog-title">
            <form method="dialog">
              <h2 id="dialog-title">Delete this image?</h2>
              <p>
                This will permanently remove the image from your library. You can’t undo this action.
              </p>
              <div class="dialog-actions">
                <button type="submit" class="button button-secondary" value="cancel">Cancel</button>
                <button type="submit" class="button button-danger" value="confirm">Delete</button>
              </div>
            </form>
          </dialog>
        `;
      }

      function render() {
        root.innerHTML = App();

        const dialog = document.getElementById("delete-dialog");
        const openButton = document.querySelector("[data-open-dialog]");

        if (openButton) {
          openButton.addEventListener("click", () => dialog.showModal());
        }

        dialog.addEventListener("close", () => {
          if (dialog.returnValue === "confirm") {
            state.isDeleted = true;
            render();
          }
        });
      }

      render();
    </script>
  </body>
</html>
